import pathlib,urllib.request,urllib.error,json,re
root=pathlib.Path('/home/appontrack/public_html')
ht=(root/'.htaccess').read_text()
bootstrap=(root/'_core/Bootstrap.php').read_text()
routes=[s.strip() for s in ht.splitlines() if s.startswith('Rewrite') and 'HTTP' not in s]
def check(path):
 req=urllib.request.Request('https://app.ontrackegy.com'+path,headers={'User-Agent':'OnTrack-root-legacy-check'})
 try:
  with urllib.request.urlopen(req,timeout=5) as r:return {'code':r.status,'path':r.url.split('app.ontrackegy.com')[-1]}
 except urllib.error.HTTPError as e:return {'code':e.code,'path':e.url.split('app.ontrackegy.com')[-1]}
 except Exception as e:return {'error':type(e).__name__}
print(json.dumps({'htaccess_rewrites':routes,'bootstrap_has_old_prefix':"$prefix='/saas/console'" in bootstrap,
 'bootstrap_has_legacy_route':"str_starts_with($uri,$prefix)" in bootstrap,
 'present_paths':{'legacy_root_dir':(root/'saas/console').exists(),'saas_dir':(root/'saas').is_dir(),'index':(root/'index.php').is_file()},
 'requests':{p:check(p) for p in ['/','/login','/saas/console/','/saas/console/login','/saas/console/?tab=settings','/saas/mobile/session.php','/mobile/session.php']}},ensure_ascii=False))
